// Reading the trigger lookup on a trigger node that never fired THROWS in
// this n8n version (confirmed via live E2E testing: running this workflow
// via Manual Trigger alone, with Execute Workflow Trigger never executing,
// crashed here) — wrap in try/catch so both "never executed" and "executed
// with zero items" degrade to the same safe default.
let trigger = {};
try {
  const triggerItems = $('When Executed by Another Workflow').all();
  trigger = triggerItems.length ? triggerItems[0].json : {};
} catch (e) { trigger = {}; }
const asOfDate = trigger.asOfDate || new Date().toISOString().slice(0, 10);
const runType = trigger.runType || 'LIVE';
// Multi-market addition: defaults to EGX so every existing caller that
// doesn't pass market (an old Execute Workflow node, a bare Manual
// Trigger run) keeps behaving exactly as before. market doubles as both
// our own stocks.exchange/scanner_runs.market value AND the EODHD
// exchange-code suffix (see 01/02/03) — true for EGX and US alike, so no
// separate markets-table lookup is needed in the daily per-stock chain;
// only 11's liquidity-threshold lookup needs real per-market config.
const market = trigger.market || 'EGX';
return [{ json: { asOfDate, runType, market } }];

function isNumber(v) { return typeof v === 'number' && Number.isFinite(v); }
function fmt(v, d) { return isNumber(v) ? v.toFixed(d) : 'unknown'; }

// Runs once for the WHOLE batch — one item per Top 10 pick arrives here
// from "Load Top 10 Scanner Results". Must loop $input.all() explicitly
// (same bug pattern found and fixed across every multi-item Code node in
// this project — confirmed via live E2E testing).

const items = $input.all();
const out = [];

for (const item of items) {
  const r = item.json;

  const sampleSize = isNumber(r.historical_sample_size) ? r.historical_sample_size : 0;
  const hasBaseRate = isNumber(r.historical_target1_hit_pct) && sampleSize > 0;
  const lowConfidenceBaseRate = hasBaseRate && sampleSize < 20;
  const baseRateLine = hasBaseRate
    ? 'Historical base rate for this scanner setup_type ("' + r.setup_type + '"), measured from ' + sampleSize +
      ' of this project\'s own past picks that reached their evaluation window: ' + fmt(r.historical_target1_hit_pct, 1) +
      '% eventually hit Target 1, ' + fmt(r.historical_stop_hit_pct, 1) + '% hit the stop/invalidation instead.' +
      (lowConfidenceBaseRate
        ? ' Sample size is small (n=' + sampleSize + ') — treat this as a weak prior, not a strong anchor.'
        : ' Use this as your starting anchor, then adjust up or down for this specific setup\'s features.')
    : 'No historical base rate is available yet for this setup_type — rely primarily on the technical factors below.';

  const prompt = [
    'You are a senior quantitative analyst practicing calibrated forecasting (the discipline used in',
    'professional forecasting tournaments: anchor on base rates, avoid round-number defaults like 50%,',
    'use the full 0-100 range when evidence warrants it, and do not simply restate the algorithmic score',
    'as your probability — reaching a specific price target within a specific number of days is a harder,',
    'less certain event than a generic composite score).',
    '',
    'Market context: this is the Egyptian Exchange (EGX) — a smaller, less liquid emerging market with',
    'higher volatility and gap risk than large-cap developed markets. Factor in wider realistic price swings.',
    '',
    'Stock: ' + r.symbol + ' (' + (r.name || 'unknown') + ')',
    'Scanner setup type: ' + r.setup_type + ' (overall rank ' + r.overall_rank + ' of the day\'s Top 10)',
    'Overall algorithmic score: ' + fmt(r.overall_score, 1) + '/100 (a composite rank score, NOT a probability)',
    'Sub-scores — Breakout: ' + fmt(r.breakout_score, 1) + ', Momentum: ' + fmt(r.momentum_score, 1) +
      ', Pullback: ' + fmt(r.pullback_score, 1) + ', Reversal: ' + fmt(r.reversal_score, 1),
    'RSI14: ' + fmt(r.rsi14, 1) + ' (>70 overbought / <30 oversold), MACD histogram: ' + fmt(r.macd_histogram, 4),
    'Trend — short-term: ' + (r.short_term_trend || 'unknown') + ', medium-term: ' + (r.medium_term_trend || 'unknown') +
      ', long-term: ' + (r.long_term_trend || 'unknown'),
    'Entry: ' + fmt(r.entry_price, 2) + ', Target 1: ' + fmt(r.target1, 2) +
      ' (potential gain ' + fmt(r.target1_gain_pct, 2) + '%), Invalidation/stop: ' + fmt(r.invalidation_price, 2) +
      ', Risk:Reward to Target 1: ' + fmt(r.risk_reward_t1, 2),
    'Estimated days to Target 1 (rough ATR-based projection from this stock\'s own volatility, not a guarantee): ' +
      (r.target1_estimated_days != null ? r.target1_estimated_days : 'unknown'),
    '',
    baseRateLine,
    '',
    'Reasoning approach — work through this before answering:',
    '1. Start from the historical base rates above (if available) as your two anchors — one for reaching',
    '   Target 1, one for hitting the stop/invalidation instead.',
    '2. List the specific factors in THIS setup that argue for a Target-1 probability HIGHER than its anchor',
    '   (e.g. strong multi-timeframe trend alignment, healthy RSI with room to run, strong R:R, short',
    '   estimated-days window relative to typical moves) — the same factors typically argue for a LOWER',
    '   stop-probability than its anchor, but do not assume they are perfectly complementary (price can also',
    '   do neither within the window).',
    '3. List the specific factors that argue for a Target-1 probability LOWER than its anchor (and usually a',
    '   HIGHER stop-probability) — e.g. RSI already overbought/oversold, weak or negative R:R, long',
    '   estimated-days window, trend timeframes disagreeing with each other, thin sub-scores relative to the',
    '   overall score, a stop that is proportionally tight relative to normal volatility.',
    '4. Net those factors against each anchor separately to reach your two final numbers — do not default to',
    '   50, to the overall algorithmic score, or to "100 minus the other number" just because it is convenient.',
    '',
    'Provide: (1) your calibrated probability (0-100) that price reaches Target 1 within the estimated-days',
    'window, (2) your calibrated probability (0-100) that the stop/invalidation price is hit before Target 1',
    'within that same window, (3) a 0-100 conviction/rank score for this setup\'s overall quality relative to',
    'the other Top 10 candidates today, (4) a brief 1-2 sentence rationale citing the specific factors that',
    'moved both probabilities away from their base rates. Be honest about uncertainty — these are probability',
    'estimates from limited technical data, not guarantees.',
  ].join('\n');

  const requestBody = {
    model: 'claude-sonnet-5',
    max_tokens: 600,
    tools: [{
      name: 'provide_assessment',
      description: 'Provide a structured probability and rank assessment for this stock setup.',
      input_schema: {
        type: 'object',
        properties: {
          target1_probability_pct: {
            type: 'number',
            description: 'Calibrated probability (0-100) of reaching Target 1 within the estimated-days window, anchored on the historical target1_hit_pct base rate then adjusted for setup-specific factors.',
          },
          stop_probability_pct: {
            type: 'number',
            description: 'Calibrated probability (0-100) that the stop/invalidation price is hit before Target 1 within the estimated-days window, anchored on the historical stop_hit_pct base rate then adjusted for setup-specific factors. Not required to sum to 100 with target1_probability_pct — price may do neither within the window.',
          },
          rank_score: {
            type: 'number',
            description: '0-100 conviction score for this setup, used to rank it against the other Top 10 candidates.',
          },
          reasoning: { type: 'string', description: '1-2 sentence rationale citing the specific factors that moved both probabilities away from their base rates.' },
        },
        required: ['target1_probability_pct', 'stop_probability_pct', 'rank_score', 'reasoning'],
      },
    }],
    tool_choice: { type: 'tool', name: 'provide_assessment' },
    messages: [{ role: 'user', content: prompt }],
  };

  out.push({ json: {
    scannerResultId: r.scanner_result_id,
    symbol: r.symbol,
    requestBodyJson: JSON.stringify(requestBody),
  } });
}

return out;

function isNumber(v) { return typeof v === 'number' && Number.isFinite(v); }
function clamp(v, lo, hi) { return Math.min(hi, Math.max(lo, v)); }

// Runs once for the WHOLE batch. itemMatching(i) pairs each response back
// to the request that produced it (same pairing pattern used everywhere in
// this project — confirmed via live E2E testing to be the only reliable
// way to line up parallel per-item chains).

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  let original;
  try { original = $('Build Prompt').itemMatching(i).json; } catch (e) { continue; }
  const row = items[i].json;

  // ANTHROPIC_API_KEY unset/invalid, rate limited, or any other API error
  // all land here the same way: no tool_use block found -> skip this row
  // rather than writing garbage. Never throws the workflow.
  const content = Array.isArray(row.content) ? row.content : [];
  const toolUse = content.find((c) => c && c.type === 'tool_use' && c.name === 'provide_assessment');
  const input = toolUse ? toolUse.input : null;

  if (!input || !isNumber(input.target1_probability_pct) || !isNumber(input.stop_probability_pct) || !isNumber(input.rank_score)) {
    out.push({ json: { scannerResultId: original.scannerResultId, _skip: true } });
    continue;
  }

  out.push({ json: {
    scannerResultId: original.scannerResultId,
    targetProbabilityPct: clamp(input.target1_probability_pct, 0, 100),
    stopProbabilityPct: clamp(input.stop_probability_pct, 0, 100),
    rankScore: clamp(input.rank_score, 0, 100),
    reasoning: typeof input.reasoning === 'string' ? input.reasoning.slice(0, 2000) : null,
    _skip: false,
  } });
}

return out;

// Runs once for the WHOLE batch — sorts whichever picks got a successful
// assessment by rank_score and assigns 1..N. A pick that failed/was
// skipped simply never reaches here (filtered by "Has Assessment?"), so
// ai_rank is only ever assigned among picks that actually got assessed.
const items = $input.all().map((i) => i.json);
const sorted = [...items].sort((a, b) => b.rankScore - a.rankScore);
const rankMap = new Map(sorted.map((it, idx) => [it.scannerResultId, idx + 1]));
return items.map((it) => ({ json: { ...it, aiRank: rankMap.get(it.scannerResultId) } }));

return [{ json: {
  workflow: '17-egx-ai-assessment',
  finishedAt: new Date().toISOString(),
} }];
